/* ---------------------------------------------------------------- panoramic band */
.band {
  position: fixed; inset: 0 0 auto 0; z-index: 40;
  height: var(--band-h);
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 0 18px 0 20px;
  background: linear-gradient(rgba(8, 9, 11, 0.92), rgba(8, 9, 11, 0.78));
