.band-sep { width: 1px; height: 20px; background: var(--line-2); }

.wave-strip {
  display: inline-flex; align-items: center; gap: 10px; min-width: 0;
  color: var(--text-2); text-decoration: none !important; font-size: 13px;
  padding: 5px 10px; margin-left: -6px; border-radius: 8px;
  transition: background var(--t-fast);
}
.wave-strip:hover { background: rgba(255, 255, 255, 0.04); }
.wave-strip .sim {
  font-size: 10px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--amber-ink); background: var(--amber-wash); padding: 2px 7px; border-radius: 5px;
}
.wave-ticks { display: inline-flex; gap: 3px; }
.wave-ticks i { width: 16px; height: 4px; border-radius: 2px; background: #252a33; }
.wave-ticks i.done { background: #4c5566; }
.wave-ticks i.now { background: var(--blue-hi); box-shadow: 0 0 10px rgba(77, 148, 255, 0.55); }
.wave-text { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wave-text b { color: var(--text); font-weight: 600; }
.telltale.pulse::before { animation: tt-pulse 1.4s ease-in-out infinite; }
@keyframes tt-pulse { 50% { opacity: 0.35; } }

.waiting {
  display: inline-flex; align-items: center; gap: 8px; height: 30px; padding: 0 12px 0 5px;
  border-radius: 999px; background: var(--blue-wash); color: var(--blue-ink);
  font-size: 12.5px; font-weight: 550; text-decoration: none !important; white-space: nowrap;
  transition: background var(--t-fast);
}
.waiting:hover { background: rgba(28, 105, 212, 0.26); }
.waiting-n { display: inline-grid; place-items: center; min-width: 21px; height: 21px; padding: 0 6px; border-radius: 999px; background: var(--blue); color: #fff; font-weight: 700; font-size: 11.5px; }

.spend { display: inline-flex; align-items: center; gap: 8px; text-decoration: none !important; color: var(--text-2); }
.spend-val { font-size: 12.5px; }
.spend-track { position: relative; width: 54px; height: 4px; border-radius: 2px; background: #1e222a; }
.spend-track span { position: absolute; inset: 0 auto 0 0; border-radius: 2px; background: #8b94a4; }
.spend-track i { position: absolute; top: -2px; width: 1px; height: 8px; background: #5c6474; }

.actor { display: inline-flex; align-items: center; gap: 8px; padding: 3px 10px 3px 3px; border-radius: 999px; transition: background var(--t-fast); }
.actor:hover { background: rgba(255, 255, 255, 0.05); }
.avatar { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 10.5px; font-weight: 700; background: #1f2a3a; color: var(--blue-ink); letter-spacing: 0.02em; }
.actor-name { font-size: 12.5px; color: var(--text-2); white-space: nowrap; }
.actor-edit .input { height: 30px; width: 180px; }
.palette-btn { gap: 6px; padding: 0 6px 0 9px; }
.palette-btn .kbd { height: 18px; min-width: 0; font-size: 10.5px; }
@media (max-width: 1080px) { .actor-name, .spend { display: none; } }
@media (max-width: 760px) { .wave-text, .waiting, .present-btn { display: none; } .band { padding: 0 12px; } }

/* ---------------------------------------------------------------- floating dock */
.dock-wrap {
  position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%); z-index: 45;
  display: flex; align-items: center; gap: 8px;
}
.dock {
  display: flex; align-items: center; gap: 2px; padding: 5px;
  background: rgba(20, 23, 29, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 16px;
  backdrop-filter: blur(18px) saturate(150%);
  -webkit-backdrop-filter: blur(18px) saturate(150%);
  box-shadow: var(--shadow-2);
}
.dock-item {
  position: relative; display: inline-flex; align-items: center; gap: 7px;
  height: 38px; padding: 0 13px; border-radius: 11px;
  color: var(--muted); text-decoration: none !important; font-size: 12.5px; font-weight: 550;
  transition: color var(--t-fast);
}
.dock-item svg { width: 17px; height: 17px; position: relative; }
.dock-item:hover { color: var(--text); }
.dock-item.active { color: #fff; }
.dock-label, .dock-badge { position: relative; }
.dock-active { position: absolute; inset: 0; border-radius: 11px; background: rgba(255, 255, 255, 0.08); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06); }
.dock-badge { min-width: 18px; height: 18px; padding: 0 5px; border-radius: 999px; background: var(--blue); color: #fff; font-size: 10.5px; font-weight: 700; display: inline-grid; place-items: center; }
.dock-search {
  width: 48px; height: 48px; border-radius: 50%;
  display: grid; place-items: center; color: var(--text-2);
  background: rgba(20, 23, 29, 0.82); border: 1px solid rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
  box-shadow: var(--shadow-2); transition: color var(--t-fast), background var(--t-fast);
}
.dock-search:hover { color: #fff; background: rgba(30, 34, 42, 0.92); }
.dock-search svg { width: 18px; height: 18px; }
@media (max-width: 860px) { .dock-label { display: none; } .dock-item { padding: 0 12px; } }
@media (max-width: 420px) { .dock-search { width: 42px; height: 42px; } .dock-wrap { gap: 6px; } }

/* ---------------------------------------------------------------- toasts */
.toasts { position: fixed; right: 20px; bottom: 90px; z-index: 80; display: flex; flex-direction: column; gap: 8px; width: min(380px, calc(100vw - 32px)); }
.toast {
  display: flex; gap: 12px; align-items: flex-start; padding: 12px 14px;
  background: rgba(22, 25, 31, 0.96); border: 1px solid var(--line-2); border-radius: 12px; box-shadow: var(--shadow-2);
  backdrop-filter: blur(12px);
}
.toast-icon { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; flex: none; }
.toast-icon svg { width: 13px; height: 13px; }
.toast-ok .toast-icon { background: var(--green-wash); color: var(--green); }
.toast-error .toast-icon { background: var(--red-wash); color: var(--red); }
.toast-title { font-weight: 600; font-size: 13px; }
.toast-body { color: var(--muted); font-size: 12.5px; margin-top: 2px; }

/* ---------------------------------------------------------------- drawer */
.drawer-scrim { position: fixed; inset: 0; z-index: 60; background: var(--scrim); }
.drawer {
  position: fixed; top: 10px; right: 10px; bottom: 10px; z-index: 61;
  width: min(560px, calc(100vw - 20px));
  background: #0d0f13; border: 1px solid var(--line-2); border-radius: var(--r-sheet);
  box-shadow: var(--shadow-2); display: flex; flex-direction: column; overflow: hidden;
}
.drawer-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 18px 20px 14px; border-bottom: 1px solid var(--line); }
.drawer-body { overflow-y: auto; padding: 18px 20px 28px; flex: 1; }

/* ---------------------------------------------------------------- command palette */
.cmdk-scrim { position: fixed; inset: 0; z-index: 90; background: var(--scrim); display: grid; place-items: start center; padding-top: 14vh; }
.cmdk-box {
  width: min(640px, calc(100vw - 32px)); background: #111318; border: 1px solid var(--line-2);
  border-radius: 14px; box-shadow: var(--shadow-2); overflow: hidden;
}
.cmdk-box [cmdk-input] {
  width: 100%; height: 52px; padding: 0 18px; border: 0; border-bottom: 1px solid var(--line);
  background: transparent; font-size: 15px; outline: none; color: var(--text);
}
.cmdk-box [cmdk-input]::placeholder { color: var(--faint); }
.cmdk-box [cmdk-list] { max-height: min(420px, 56vh); overflow-y: auto; padding: 6px; }
.cmdk-box [cmdk-group-heading] { padding: 10px 12px 6px; font-size: 11px; color: var(--faint); font-weight: 600; }
.cmdk-box [cmdk-item] {
  display: flex; align-items: center; gap: 10px; height: 40px; padding: 0 12px; border-radius: 8px;
  font-size: 13.5px; color: var(--text-2); cursor: pointer;
}
.cmdk-box [cmdk-item] svg { width: 16px; height: 16px; color: var(--muted); }
.cmdk-box [cmdk-item][data-selected="true"] { background: var(--hover); color: var(--text); }
.cmdk-box [cmdk-empty] { padding: 22px; text-align: center; color: var(--muted); }
.cmdk-hint { margin-left: auto; color: var(--faint); font-size: 12px; }

/* ---------------------------------------------------------------- story mode */
.story {
  position: fixed; left: 20px; bottom: 20px; z-index: 50; width: min(380px, calc(100vw - 40px));
  padding: 14px 16px 14px; border-radius: 14px;
  background: rgba(16, 20, 28, 0.94); border: 1px solid #2a3446; box-shadow: var(--shadow-2);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
  display: flex; flex-direction: column; gap: 10px;
}
.story-top { display: flex; align-items: center; justify-content: space-between; }
.story-step { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--blue-ink); font-weight: 600; }
.story-title { font-size: 16px; font-weight: 600; font-stretch: 108%; line-height: 1.3; }
.story-say { margin-top: 6px; font-size: 13px; line-height: 1.55; color: var(--text-2); }
.story-dots { display: flex; gap: 4px; }
.story-dots i { flex: 1; height: 3px; border-radius: 2px; background: #252b36; }
.story-dots i.past { background: #4c5566; }
.story-dots i.on { background: var(--blue-hi); }
.story-nav { display: flex; justify-content: space-between; gap: 8px; }
.present-btn { gap: 6px; }
@media (max-width: 1280px) { .story { bottom: 88px; } }

/* ---------------------------------------------------------------- phone */
@media (max-width: 760px) {
  .band-left { min-width: 0; overflow: hidden; flex: 1; }
  .band-right { flex: none; gap: 6px; }
  .band-sep { display: none; }
  .actor { padding: 2px; }
}
@media (max-width: 420px) {
  .wave-ticks { display: none; }
  .brand-name { display: none; }
  .dock-item { padding: 0 9px; }
}
@media (max-width: 760px) {
  .palette-btn .kbd { display: none; }
  .palette-btn { padding: 0 8px; }
  .band { overflow: hidden; }
}
.sec-label { font-size: var(--fs-small); color: var(--muted); font-weight: 550; margin-bottom: 8px; }

/* decision ask */
.ask-label { font-size: var(--fs-small); color: var(--blue-ink); font-weight: 600; margin-bottom: 8px; }
.ask-text { font-size: 19px; line-height: 1.5; color: #fff; font-weight: 450; max-width: 68ch; }
.ask-text-sm { font-size: 16px; color: var(--text); }
.ask-need { margin-top: 10px; color: var(--text-2); line-height: 1.6; max-width: 72ch; }

/* voice by market */
.voice { display: flex; flex-direction: column; gap: 9px; }
.voice-row { display: grid; grid-template-columns: 150px minmax(60px, 1fr) auto; gap: 12px; align-items: center; font-size: 13px; }
.voice-label { color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.voice-track { height: 6px; background: #1a1e25; border-radius: 3px; overflow: hidden; }
.voice-track span { display: block; height: 100%; background: linear-gradient(90deg, #2f5fa6, var(--blue-hi)); border-radius: 3px; }
.voice-num { font-size: 12.5px; white-space: nowrap; }
.voice-silent { grid-column: 2 / -1; color: var(--amber-ink); font-size: 12.5px; }
@media (max-width: 640px) { .voice-row { grid-template-columns: minmax(0, 1fr); gap: 4px; } .voice-silent { grid-column: auto; } }

/* quotes */
.quotes { display: flex; flex-direction: column; }
.quote { margin: 0; position: relative; padding: 12px 0 12px 28px; border-top: 1px solid var(--line); }
.quote:first-child { border-top: 0; padding-top: 4px; }
.quote-mark { position: absolute; left: 0; top: 14px; width: 15px; height: 15px; color: var(--blue-hi); opacity: 0.8; }
.quote blockquote { margin: 0; color: var(--text); line-height: 1.55; font-size: 13.5px; }
.quote figcaption { margin-top: 6px; font-size: 11.5px; color: var(--muted); }

/* study & web */
.sw { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.sw-list { margin: 0; padding-left: 16px; color: var(--text-2); font-size: 13px; line-height: 1.55; display: flex; flex-direction: column; gap: 4px; }
.sw-list li::marker { color: var(--faint); }
@media (max-width: 760px) { .sw { grid-template-columns: minmax(0, 1fr); } }

/* conflict */
.conflict { display: flex; gap: 12px; padding: 14px 16px; border-radius: 10px; background: var(--amber-wash); box-shadow: inset 0 0 0 1px rgba(245, 165, 36, 0.25); }
.conflict svg { width: 18px; height: 18px; color: var(--amber); flex: none; margin-top: 1px; }
.conflict-title { font-weight: 600; color: var(--amber-ink); margin-bottom: 4px; }
.conflict p { color: var(--text-2); font-size: 13px; line-height: 1.55; }

/* market table */
.mt td { padding-top: 9px; padding-bottom: 9px; }
.mt-target { font-weight: 550; white-space: nowrap; }
.mt-focus { background: rgba(28, 105, 212, 0.07); }
.pchoice { display: inline-flex; gap: 3px; padding: 2px; border-radius: 8px; background: #0a0c0f; box-shadow: inset 0 0 0 1px var(--line); }
.pchoice-b { height: 24px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--faint); transition: background var(--t-fast), color var(--t-fast); }
.pchoice-b:hover { color: var(--text); background: var(--hover); }
.pchoice-b[aria-checked="true"].pc-must { background: var(--blue); color: #fff; }
.pchoice-b[aria-checked="true"].pc-should { background: var(--blue-wash); color: var(--blue-ink); box-shadow: inset 0 0 0 1px var(--blue-line); }
.pchoice-b[aria-checked="true"].pc-could { background: #1d2129; color: var(--text-2); box-shadow: inset 0 0 0 1px var(--line-2); }

/* gates */
.gates { display: flex; flex-direction: column; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--line); }
.gate + .gate { border-top: 1px solid var(--line); }
.gate-head { width: 100%; display: grid; grid-template-columns: 150px 70px 1fr 16px; gap: 10px; align-items: center; padding: 10px 14px; text-align: left; border-radius: 10px; }
.gate-head:hover { background: rgba(255,255,255,0.02); }
.gate-word { font-size: 12.5px; color: var(--text-2); font-variant-numeric: proportional-nums; }
.gate-effect { font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gate-chev { width: 15px; height: 15px; color: var(--faint); transition: transform var(--t-fast); }
.gate-chev.up { transform: rotate(180deg); }
.gate-body { padding: 2px 14px 12px; display: flex; flex-direction: column; gap: 10px; }
.gate-why { margin-top: 5px; color: var(--text-2); font-size: 13px; line-height: 1.55; }
.gate-fail { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 0 10px 10px; padding: 10px 12px; border-radius: 8px; background: var(--red-wash); color: var(--red-ink); font-size: 13px; }
.gate-fail svg { width: 16px; height: 16px; }
@media (max-width: 640px) { .gate-head { grid-template-columns: 1fr auto 16px; } .gate-effect { display: none; } }

/* assumptions & uncertainties */
.au { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.au-label { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.au ul { margin: 0; padding-left: 16px; color: var(--text-2); font-size: 13px; line-height: 1.55; display: flex; flex-direction: column; gap: 5px; }
@media (max-width: 760px) { .au { grid-template-columns: minmax(0, 1fr); } }
.mt-ai { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; }
.quote:first-child .quote-mark { top: 6px; }
.hchart { position: relative; }
.hchart svg { display: block; overflow: visible; }
.hc-grid { stroke: #161a20; stroke-width: 1; }
.hc-band { stroke: #343b47; stroke-width: 1; stroke-dasharray: 3 4; }
.hc-axis { fill: var(--faint); font-size: 10.5px; font-family: var(--font); }
.hc-line { fill: none; stroke: #3a414e; stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.hc-dot { fill: #3a414e; cursor: pointer; }
.hc-s.focus .hc-line { stroke: var(--blue-hi); stroke-width: 2.2; }
.hc-s.focus .hc-dot { fill: var(--blue-hi); }
.hc-end { fill: var(--blue-ink); font-size: 11px; font-family: var(--font); font-variant-numeric: proportional-nums; }
.hc-tip {
  position: absolute; left: 30px; top: 0; padding: 8px 10px; border-radius: 8px; max-width: 420px;
  background: rgba(20, 23, 29, 0.96); border: 1px solid var(--line-2); font-size: 12px; box-shadow: var(--shadow-1); pointer-events: none;
}

.wf { display: flex; flex-direction: column; gap: 7px; }
.wf-row { display: grid; grid-template-columns: 190px minmax(0, 1fr) 54px; gap: 12px; align-items: center; font-size: 12.5px; }
.wf-label { color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wf-track { position: relative; height: 12px; }
.wf-bar { position: absolute; top: 2px; bottom: 2px; border-radius: 2px; background: #3f6fb0; }
.wf-c .wf-bar { background: var(--amber); opacity: 0.85; }
.wf-m .wf-bar { background: #6a7282; }
.wf-t { margin-top: 4px; padding-top: 9px; border-top: 1px solid var(--line); }
.wf-t .wf-label { color: var(--text); font-weight: 600; }
.wf-t .wf-bar { background: var(--blue-hi); top: 0; bottom: 0; }
.wf-guide { position: absolute; top: -4px; bottom: -4px; width: 1px; background: #8892a2; }
.wf-val { text-align: right; color: var(--text-2); }
.wf-t .wf-val { color: #fff; font-weight: 600; }
@media (max-width: 640px) { .wf-row { grid-template-columns: 120px minmax(0, 1fr) 46px; } }

