.briefing { display: flex; flex-direction: column; gap: 18px; }
.brief-top { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: 18px; align-items: stretch; }
.brief-mid { display: grid; grid-template-columns: minmax(0, 8fr) minmax(0, 4fr); gap: 18px; align-items: start; }
@media (max-width: 1100px) { .brief-top, .brief-mid { grid-template-columns: minmax(0, 1fr); } }

/* ---------------------------------------------------------------- recap */
.recap { position: relative; overflow: hidden; padding: 26px 30px 28px; display: flex; flex-direction: column; }
.recap-meta { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.recap-title { position: relative; margin-top: 18px; font-size: 34px; line-height: 1.12; font-stretch: 112%; font-weight: 600; letter-spacing: -0.02em; max-width: 22ch; }
.recap-text { position: relative; margin-top: 16px; font-size: 17px; line-height: 1.7; color: var(--text-2); max-width: 64ch; }
.recap-text b { color: #fff; font-weight: 600; }
.recap-text .chip { vertical-align: 1px; }
.recap-actions { position: relative; margin-top: auto; padding-top: 26px; display: flex; gap: 10px; flex-wrap: wrap; }

/* ---------------------------------------------------------------- portfolio pulse */
.pulse { display: flex; flex-direction: column; }
.pulse-grid { padding: 10px 14px 16px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.pulse-row { display: grid; grid-template-columns: 92px repeat(4, minmax(0, 1fr)); gap: 6px; align-items: stretch; }
.pulse-headrow { align-items: end; }
.pulse-col { font-size: var(--fs-micro); color: var(--muted); padding: 0 8px 2px; font-weight: 550; }
.pulse-car { font-size: 12.5px; color: var(--text-2); font-weight: 550; display: flex; align-items: center; }
.pulse-cell {
  text-align: left; border-radius: 9px; padding: 10px 10px 9px;
  background: #0b0d11; box-shadow: inset 0 0 0 1px var(--line);
  display: grid; grid-template-columns: auto 1fr; align-items: baseline; column-gap: 6px; row-gap: 6px;
  transition: background var(--t-fast), box-shadow var(--t-fast), transform var(--t-fast);
  min-height: 78px;
}
.pulse-cell:hover { background: #10141b; box-shadow: inset 0 0 0 1px var(--blue-line); }
.pulse-none { background: repeating-linear-gradient(135deg, transparent 0 6px, rgba(255,255,255,0.018) 6px 7px); box-shadow: inset 0 0 0 1px rgba(255,255,255,0.025); }
.pulse-must { font-size: 26px; color: #fff; font-stretch: 106%; }
.pulse-unit { font-size: 11px; color: var(--muted); }
.pulse-bar { grid-column: 1 / -1; display: flex; height: 4px; border-radius: 2px; overflow: hidden; background: #1a1e25; gap: 1px; }
.pulse-bar i { display: block; height: 100%; }
.pulse-bar .m { background: var(--blue-hi); }
.pulse-bar .s { background: #3f6fb0; }
.pulse-bar .c { background: #3b414d; }
.pulse-foot { grid-column: 1 / -1; font-size: 11px; min-height: 16px; line-height: 1.3; }
.pulse-foot .telltale { white-space: normal; }
.pulse-foot .telltale { font-size: 11px; }
@media (max-width: 560px) { .pulse-row { grid-template-columns: 70px repeat(4, minmax(0, 1fr)); } .pulse-must { font-size: 20px; } }

/* ---------------------------------------------------------------- new requirements */
.newreqs { display: flex; flex-direction: column; gap: 4px; padding-top: 6px; }
.newreq { text-align: left; padding: 10px 10px; margin: 0 -10px; border-radius: 9px; display: grid; gap: 3px; transition: background var(--t-fast); }
.newreq:hover { background: var(--hover); }
.newreq-title { font-weight: 550; color: var(--text); line-height: 1.35; }
.newreq-meta { font-size: 12px; }

/* ---------------------------------------------------------------- feed */
.feed { list-style: none; margin: 0; padding: 6px 8px 10px; }
.feed-item {
  width: 100%; text-align: left; display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 12px; align-items: start;
  padding: 10px 10px; border-radius: 9px; transition: background var(--t-fast);
}
.feed-item:not(:disabled):hover { background: var(--hover); }
.feed-item:disabled { cursor: default; }
.feed-icon { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; }
.feed-icon svg { width: 15px; height: 15px; }
.who-ai { background: var(--blue-wash); color: var(--blue-ink); }
----
.decide { display: grid; grid-template-columns: 312px minmax(0, 1fr); gap: 22px; align-items: start; max-width: 1560px; }
@media (max-width: 1000px) { .decide { grid-template-columns: minmax(0, 1fr); } }

/* ---------------------------------------------------------------- queue rail */
.qrail {
  position: sticky; top: calc(var(--band-h) + 20px);
  max-height: calc(100vh - var(--band-h) - 120px);
  display: flex; flex-direction: column; gap: 12px;
}
@media (max-width: 1000px) { .qrail { position: static; max-height: 360px; } }
.qrail-head { display: flex; flex-direction: column; gap: 10px; }
.qscope { height: 32px; padding: 0 10px; font-size: 12.5px; }
.qrail-list { overflow-y: auto; margin-right: -8px; padding-right: 8px; display: flex; flex-direction: column; gap: 14px; }
.qgroup-h { display: flex; align-items: center; gap: 7px; font-size: 11.5px; color: var(--muted); font-weight: 600; margin: 0 0 6px 2px; letter-spacing: 0; }
.qgroup-h svg { width: 13px; height: 13px; }
.qitem {
  position: relative; width: 100%; text-align: left; display: flex; flex-direction: column; gap: 4px;
  padding: 9px 12px 9px 14px; border-radius: 9px; transition: background var(--t-fast);
}
.qitem:hover { background: var(--hover); }
.qitem.on { background: rgba(28, 105, 212, 0.13); box-shadow: inset 0 0 0 1px var(--blue-line); }
.qitem.on .qitem-title { color: #fff; }
.qitem-title { font-size: 13px; font-weight: 550; color: var(--text); line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.qitem-sub { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--muted); min-width: 0; }
.qitem-sub .ellipsis { min-width: 0; flex: 1; }
.qrail-keys { display: flex; align-items: center; gap: 4px; padding-top: 8px; border-top: 1px solid var(--line); }

/* ---------------------------------------------------------------- workspace */
.workspace { min-width: 0; }
.ws-empty { padding: 40px; }
.ws { display: flex; flex-direction: column; gap: 14px; }
.ws-head { display: flex; flex-direction: column; gap: 10px; padding: 2px 2px 6px; }
.ws-open { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; }
.ws-title { font-size: 30px; line-height: 1.15; font-weight: 600; letter-spacing: -0.02em; font-stretch: 108%; max-width: 30ch; }
.ws-grid { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); gap: 14px; align-items: start; }
@media (max-width: 1280px) { .ws-grid { grid-template-columns: minmax(0, 1fr); } }
.ws-main, .ws-side { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.ws-pad { padding: 18px 20px; }
.ws-table { padding: 4px 6px 8px; overflow-x: auto; }

/* ---------------------------------------------------------------- decision panel */
.decision { padding: 16px 18px 18px; display: flex; flex-direction: column; gap: 14px; border-color: #283245; background: linear-gradient(#10141b, #0e1116); }
.ws-side .decision { box-shadow: var(--shadow-1); }
.decision-choices { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.dchoice {
  height: 46px; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-weight: 600; font-size: 14px; color: var(--text-2);
  background: #0b0d11; box-shadow: inset 0 0 0 1px var(--line-2);
